mapper.update:
update batch_transfer_task
task_name = #{taskName}, task_description = #{taskDescription}, status = #{status}, started_at = #{startedAt}, update_by = #{updateBy}, update_time = now()
where id = #{id}

mapper.select:
select 
from batch_transfer_task

    deleted = 0
    and status = #{status}
    and source_agent_id = #{sourceAgentId}
    and create_by = #{createBy}

order by create_time desc
